style.css:
/* ===== Purple Theme for Stylish ===== */

/* Background & Text */
body {
    background-color: #1a1a2e !important; /* deep purple background */
    color: #e0e0ff !important; /* soft light text */
    font-family: 'Segoe UI', sans-serif !important;
}

/* Links */
a {
    color: #a970ff !important; /* light purple links */
    text-decoration: none !important;
    transition: color 0.2s ease-in-out;
}

a:hover {
    color: #d6b3ff !important; /* brighter purple on hover */
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    background: linear-gradient(135deg, #6a11cb, #a970ff) !important;
    border: none !important;
    color: white !important;
    padding: 8px 14px !important;
    border-radius: 8px !important;
    cursor: pointer !important;
    transition: transform 0.2s ease-in-out;
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    transform: scale(1.05);
    background: linear-gradient(135deg, #8e2de2, #b983ff) !important;
}

/* Inputs & Textareas */
input, textarea, select {
    background-color: #2a2a40 !important;
    border: 1px solid #6a11cb !important;
    color: #e0e0ff !important;
    padding: 6px !important;
    border-radius: 6px !important;
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
    color: #c8a2ff !important;
}

/* Cards / Containers */
div, section, article {
    background-color: #232344 !important;
    border-radius: 10px !important;
    padding: 10px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #1a1a2e;
}

::-webkit-scrollbar-thumb {
    background: #6a11cb;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #8e2de2;
}
